		     /*updateSellerMdCmChemicalMatSend*/
                   UPDATE KEP_CMC_REQ REQ
                   SET REQ_STATUS = 'S'  
                     , STOA_DATE = SYSDATE
                     , STOA_USER_ID = #{USER_ID}
                     , MSDS_NO = #{st_msds_no}
                     , MSDS_NO_FILEKEY = #{st_msds_file_key}
                     , CMC_HARMFUL_YN = #{st_harmful_yn}
                     , CMC_USE_CODE = DECODE(#{st_harmful_yn},'Y',#{st_use_cd},NULL)
                     , CMC_INFO_LEVEL = DECODE(#{st_harmful_yn},'Y',#{st_info_level},NULL)
                     , CMC_INFO_UNIT = DECODE(#{st_harmful_yn},'Y',#{st_info_unit},NULL)
                     , AGENT_NOTE = #{st_agent_note}
                     , KEP_NOTE = #{st_kep_note}
                     , TEMP_COND = #{st_temp_cond}
                     , TEMP_RANGE = REPLACE(#{st_temp_range}, '''')
                     , CHANGE_DATE = SYSDATE
                     , CHANGE_USER_ID = #{USER_ID}
                 WHERE REQ.REQ_NO = #{st_req_no}


		     /*updateSellerMdCmChemicalMatSendV2*/
                   UPDATE KEP_CMC_REQ REQ
                   SET REQ_STATUS = 'S'
                     , STOA_DATE = SYSDATE
                     , STOA_USER_ID = #{USER_ID}
                     , MSDS_NO = #{st_msds_no}
                     , MSDS_NO_FILEKEY = #{st_msds_file_key}
                     , CMC_HARMFUL_YN = #{st_harmful_yn}
                     , CMC_USE_CODE = DECODE(#{st_harmful_yn},'Y',#{st_use_cd},NULL)
                     , CMC_INFO_LEVEL = DECODE(#{st_harmful_yn},'Y',#{st_info_level},NULL)
                     , CMC_INFO_UNIT = DECODE(#{st_harmful_yn},'Y',#{st_info_unit},NULL)
                     , AGENT_NOTE = #{st_agent_note}
                     , KEP_NOTE = #{st_kep_note}
                     , TEMP_COND = #{st_temp_cond}
                     , TEMP_RANGE = REPLACE(#{st_temp_range}, '''')
                     , CHANGE_DATE = SYSDATE
                     , CHANGE_USER_ID = #{USER_ID}
                 WHERE REQ.REQ_NO = #{st_req_no}


